package edu.pe.cibertec.saibm.inventario.infrastructure.messaging; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.amqp.core.*; import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter; import org.springframework.context.annotation.*; @Configuration public class RabbitConfig {public static final String EXCHANGE="saibm.inventory.v1",HOLD_QUEUE="inventory-hold-requested",RELEASE_QUEUE="inventory-release-requested",DLQ="inventory-dlq"; @Bean Jackson2JsonMessageConverter rabbitMessageConverter(ObjectMapper mapper){return new Jackson2JsonMessageConverter(mapper);} @Bean TopicExchange inventoryExchange(){return new TopicExchange(EXCHANGE,true,false);}@Bean Queue holdQueue(){return QueueBuilder.durable(HOLD_QUEUE).deadLetterExchange(EXCHANGE).deadLetterRoutingKey(DLQ).build();}@Bean Queue releaseQueue(){return QueueBuilder.durable(RELEASE_QUEUE).deadLetterExchange(EXCHANGE).deadLetterRoutingKey(DLQ).build();}@Bean Queue deadLetterQueue(){return QueueBuilder.durable(DLQ).build();}@Bean Binding holdBinding(){return BindingBuilder.bind(holdQueue()).to(inventoryExchange()).with("InventoryHoldRequested.v1");}@Bean Binding releaseBinding(){return BindingBuilder.bind(releaseQueue()).to(inventoryExchange()).with("InventoryReleaseRequested.v1");}@Bean Binding dlqBinding(){return BindingBuilder.bind(deadLetterQueue()).to(inventoryExchange()).with(DLQ);}}
